# ---------------------------------------------------------------------------
# Batch C — strain as post-processing: the StrainWindow3D clone (strain window,
# param panel with the coordinate-system control, field selector, navigator)
# plus the sidebar's "Open Strain Window" button. Strings shared with the 2D
# strain window are copied verbatim from the al_dic catalogs; the
# coordinate-system family is new. "O"/"+X"/"+Y" pick-marker labels and the
# axes readout are locale-invariant math notation by design.
# ---------------------------------------------------------------------------

_WIN_TOOLTIP = (
    "Side length, in pixels, of the square window around each node used to "
    "fit the local displacement gradient (the virtual strain gauge).\n\n"
    "• Larger window → smoother strain, lower spatial resolution.\n"
    "• Smaller window → sharper strain, more noise.\n"
    "• Must span at least 3×3 nodes: use ≥ 2 × node spacing + 1 px."
)
_SMOOTH_TOOLTIP = (
    "Gaussian smoothing of the displacement field before the gradient fit.\n"
    "σ is the kernel width; step = DIC node spacing.\n"
    "  Light  (0.5 × step): subtle, preserves fine features.\n"
    "  Medium (1 × step): balanced, for noisy data.\n"
    "  Strong (2 × step) ⚠: aggressive, may blur real gradients."
)
_COORD_LOCAL_TIP = (
    "Per-node tangent plane fitted to the reference surface: z is the surface "
    "normal pointing toward the camera, x is the left-camera +X projected "
    "onto the plane, y = z × x. The right default for curved specimens."
)
_COORD_CAM_TIP = (
    "Report strain in the fixed left-camera (world) axes. Meaningful for "
    "flat specimens aligned with the image plane."
)
_COORD_SPEC_TIP = (
    "A fixed specimen frame built from 3 picked points on the reference "
    "image: Origin, a point along +X, and a point on the +Y side."
)
_WIN_WARNING = (
    "⚠ Window radius ({0} px) < node spacing ({1} px); the plane fit needs "
    "a 3×3 node gauge. Use ≥ {2} px."
)

